-- pgnative-A: convert an OLD-way scratch (padqa2) to the native schema. Generated by dbmigrate -mode native-convert.
-- Idempotent. NOT executed by the worker. Ends in ROLLBACK: switch to COMMIT on the scratch only.
BEGIN;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE SCHEMA IF NOT EXISTS app;
CREATE OR REPLACE FUNCTION app.norm(x text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS
$$ SELECT lower(public.unaccent('public.unaccent'::regdictionary,
        regexp_replace(normalize(rtrim(x), NFKC), E'[\u200B-\u200D\u2060\uFEFF]', '', 'g'))) $$;
CREATE OR REPLACE FUNCTION app.norm_ascii(x text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $$ SELECT lower(rtrim(x)) $$;
CREATE TEMP TABLE IF NOT EXISTS _pgn_views ON COMMIT DROP AS SELECT c.relname::text AS relname, pg_get_viewdef(c.oid) AS def FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind = 'v';
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT relname FROM _pgn_views LOOP EXECUTE format('DROP VIEW IF EXISTS public.%I', r.relname); END LOOP;
END $pgn$;
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT DISTINCT con.conrelid::regclass::text AS t, con.conname, con.contype FROM pg_constraint con
  JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey)
  WHERE con.connamespace = 'public'::regnamespace AND (a.attname LIKE '%__wk' OR a.attname LIKE '%__pad')
  ORDER BY (con.contype = 'f') DESC, 1, 2
LOOP EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', r.t, r.conname); END LOOP;
END $pgn$;
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT c.oid::regclass::text AS i FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'i' AND (c.relname LIKE 'ixwk__%' OR c.relname LIKE 'ixpad__%')
LOOP EXECUTE format('DROP INDEX IF EXISTS %s', r.i); END LOOP;
END $pgn$;
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT a.attrelid::regclass::text AS t, a.attname FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'r' AND a.attnum > 0 AND NOT a.attisdropped AND (a.attname LIKE '%__wk' OR a.attname LIKE '%__pad')
  ORDER BY (a.attgenerated <> '') DESC, 1, 2
LOOP EXECUTE format('ALTER TABLE %s DROP COLUMN IF EXISTS %I', r.t, r.attname); END LOOP;
END $pgn$;
CREATE OR REPLACE FUNCTION dbmigrate.on_update_ts() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  a text; c text; kind text; fsp text; ts timestamptz; g name; explicit text;
  o jsonb := to_jsonb(OLD); n jsonb := to_jsonb(NEW); patch jsonb := '{}'::jsonb;
BEGIN
  explicit := COALESCE(current_setting('dbmigrate.onupd_explicit', true), '');
  PERFORM set_config('dbmigrate.onupd_explicit', '', true);
  -- Fail closed: a mark from another table means a mark was not consumed by
  -- its own refresh (e.g. a foreign BEFORE trigger returned NULL in between).
  IF explicit <> '' AND EXISTS (SELECT 1 FROM unnest(string_to_array(explicit, ',')) m WHERE split_part(m, ':', 1) <> TG_RELID::text) THEN
    RAISE EXCEPTION 'dbmigrate.on_update_ts: stale explicit-column mark % (unconsumed mark trigger)', explicit;
  END IF;
  FOR g IN SELECT attname FROM pg_attribute WHERE attrelid = TG_RELID AND attnum > 0 AND NOT attisdropped AND attgenerated <> '' LOOP
    o := o - g::text; n := n - g::text;
  END LOOP;
  FOREACH a IN ARRAY TG_ARGV LOOP
    c := split_part(ltrim(a, '-'), ':', 1);
    o := o - c; n := n - c;
  END LOOP;
  IF o IS NOT DISTINCT FROM n THEN RETURN NEW; END IF;
  FOREACH a IN ARRAY TG_ARGV LOOP
    CONTINUE WHEN left(a, 1) = '-';
    c := split_part(a, ':', 1); kind := split_part(a, ':', 2); fsp := split_part(a, ':', 3);
    CONTINUE WHEN position(',' || TG_RELID::text || ':' || c || ',' IN ',' || explicit || ',') > 0;
    ts := CASE fsp WHEN '0' THEN date_trunc('second', statement_timestamp()) WHEN '3' THEN date_trunc('milliseconds', statement_timestamp()) WHEN '6' THEN statement_timestamp() END;
    IF ts IS NULL THEN RAISE EXCEPTION 'dbmigrate.on_update_ts: unsupported fsp % for %', fsp, c; END IF;
    IF (to_jsonb(NEW) -> c) IS NOT DISTINCT FROM (to_jsonb(OLD) -> c) THEN
      patch := patch || jsonb_build_object(c, CASE WHEN kind = 'tz' THEN to_jsonb(ts) ELSE to_jsonb(ts AT TIME ZONE 'UTC') END);
    END IF;
  END LOOP;
  IF patch <> '{}'::jsonb THEN NEW := jsonb_populate_record(NEW, patch); END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION dbmigrate.on_update_mark() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cur text := COALESCE(current_setting('dbmigrate.onupd_explicit', true), '');
BEGIN
  PERFORM set_config('dbmigrate.onupd_explicit', CASE WHEN cur = '' THEN '' ELSE cur || ',' END || TG_RELID::text || ':' || TG_ARGV[0], true);
  RETURN NEW;
END $$;
