DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT c.oid::regclass::text AS i FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND pg_get_indexdef(x.indexrelid) LIKE '%dbmigrate.ci_ai%'
LOOP RAISE EXCEPTION 'pgnative convert: index % still uses dbmigrate.ci_ai in an expression (unplanned object)', r.i; END LOOP;
END $pgn$;
CREATE TEMP TABLE IF NOT EXISTS _pgn_gen ON COMMIT DROP AS SELECT a.attrelid::regclass::text AS t, a.attname, format_type(a.atttypid, a.atttypmod) AS typ, pg_get_expr(d.adbin, d.adrelid) AS expr, a.attnotnull AS nn, a.attnum FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind = 'r' AND a.attgenerated = 's' AND NOT a.attisdropped AND EXISTS (SELECT 1 FROM pg_attribute b JOIN pg_collation co ON co.oid = b.attcollation JOIN pg_namespace cn ON cn.oid = co.collnamespace WHERE b.attrelid = a.attrelid AND cn.nspname = 'dbmigrate' AND b.attnum > 0 AND NOT b.attisdropped);
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT t, attname FROM _pgn_gen ORDER BY t, attnum LOOP EXECUTE format('ALTER TABLE %s DROP COLUMN %I', r.t, r.attname); END LOOP;
END $pgn$;
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT a.attrelid::regclass::text AS t, a.attname, format_type(a.atttypid, a.atttypmod) AS typ
  FROM pg_attribute a JOIN pg_collation co ON co.oid = a.attcollation JOIN pg_namespace cn ON cn.oid = co.collnamespace
  JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE cn.nspname = 'dbmigrate' AND n.nspname = 'public' AND c.relkind = 'r' AND a.attnum > 0 AND NOT a.attisdropped
  ORDER BY 1, 2
LOOP EXECUTE format('ALTER TABLE %s ALTER COLUMN %I TYPE %s COLLATE "default"', r.t, r.attname, r.typ); END LOOP;
END $pgn$;
DO $pgn$ DECLARE r record; BEGIN
FOR r IN SELECT t, attname, typ, expr, nn FROM _pgn_gen ORDER BY t, attnum LOOP EXECUTE format('ALTER TABLE %s ADD COLUMN %I %s GENERATED ALWAYS AS (%s) STORED', r.t, r.attname, r.typ, r.expr); IF r.nn THEN EXECUTE format('ALTER TABLE %s ALTER COLUMN %I SET NOT NULL', r.t, r.attname); END IF; END LOOP;
END $pgn$;
